import React, { useEffect, useState } from 'react';
import { doctorApi } from '../../api/doctorApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const AllPatients = () => {
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchPatients = async () => {
      try {
        const response = await doctorApi.getAllPatients();
        if (response.success) {
          setPatients(response.patients);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch patients');
      } finally {
        setLoading(false);
      }
    };

    fetchPatients();
  }, []);

  if (loading) return <Loader />;

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8 fade-in">
        <h1 className="text-4xl font-bold text-gray-800 mb-2">All Patients</h1>
        <p className="text-gray-600 text-lg">View all registered patients in the system</p>
      </div>

      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      {patients.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {patients.map((patient) => (
            <Card key={patient._id} hover className="border-2 border-gray-200 hover:border-blue-300">
              <div className="text-center mb-4">
                <div className="w-20 h-20 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <span className="text-white font-bold text-2xl">
                    {patient.user?.name?.charAt(0) || 'P'}
                  </span>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-1">
                  {patient.user?.name || 'N/A'}
                </h3>
                <p className="text-sm text-gray-600">{patient.user?.email || 'N/A'}</p>
              </div>

              <div className="space-y-3 text-sm border-t border-gray-200 pt-4">
                <div className="flex items-center justify-between">
                  <span className="text-gray-600">Phone:</span>
                  <span className="font-medium text-gray-800">{patient.user?.phone || 'N/A'}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-gray-600">Gender:</span>
                  <span className="font-medium text-gray-800">{patient.gender || 'N/A'}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-gray-600">Date of Birth:</span>
                  <span className="font-medium text-gray-800">
                    {patient.dateOfBirth ? new Date(patient.dateOfBirth).toLocaleDateString() : 'N/A'}
                  </span>
                </div>
                {patient.bloodGroup && (
                  <div className="flex items-center justify-between">
                    <span className="text-gray-600">Blood Group:</span>
                    <span className="font-medium text-red-600">{patient.bloodGroup}</span>
                  </div>
                )}
                <div className="pt-3 border-t border-gray-200">
                  <span className="text-gray-600 text-xs block mb-1">Address:</span>
                  <span className="text-gray-800 text-sm">{patient.address || 'N/A'}</span>
                </div>
                {patient.emergencyContact?.name && (
                  <div className="pt-3 border-t border-gray-200">
                    <span className="text-gray-600 text-xs block mb-1">Emergency Contact:</span>
                    <span className="text-gray-800 text-sm">
                      {patient.emergencyContact.name} ({patient.emergencyContact.relation})
                    </span>
                    {patient.emergencyContact.phone && (
                      <span className="text-gray-600 text-xs block mt-1">
                        {patient.emergencyContact.phone}
                      </span>
                    )}
                  </div>
                )}
              </div>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <div className="text-center py-12">
            <svg className="w-16 h-16 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            <p className="text-gray-600 text-lg">No patients found</p>
          </div>
        </Card>
      )}
    </div>
  );
};

export default AllPatients;
